/**
 * The ready-made pages, by key. Every page mounts at its default path; give a
 * key a path to mount the page there instead. An app page at a page's path
 * always wins: the module detects it and mounts nothing there.
 */
export interface ModulePagesOptions {
  /** Where an invited person accepts a workspace invitation (private). Default `/accept-invitation`; keep it equal to the Convex-side `organization.invitationPath`. */
  acceptInvitation?: string
  /** Where a person approves or denies an agent's request for access (private). Default `/oauth/consent`; keep it equal to the Convex-side `mcp.consentPath`. */
  agentConsent?: string
  /** The sign-in page (public), and where the auth middleware sends a signed-out visitor. Default `/login`. */
  login?: string
  /** The pricing page (public). Default `/pricing`. */
  pricing?: string
  /** The account profile (private). Default `/profile`. */
  profile?: string
  /** Passkeys, sessions and account deletion (private). Default `/security`. */
  security?: string
  /** Workspace, plan and credit settings (private). Default `/settings`. */
  settings?: string
}
